def fort(decl, body): return 'program lesson\n  implicit none\n'+decl+'\n'+body+'\nend program lesson\n'
course('fortran','Fortran','fortran','Examples use Fortran 2008 features supported by GNU Fortran 10 or later.','Install GNU Fortran. Save each example as lesson.f90, run gfortran -std=f2008 lesson.f90 -o lesson, then run it.','Fortran is a language used for science and number-heavy work. It has strong tools for arrays.',[
L('first-message','Write a greeting','A program block holds the steps. The A format writes character text.',fort('', 'write(*,\'(A)\') "Hello, Asha!"'),'Hello, Asha!','Change the name.','implicit none makes you declare variable types instead of guessing them.'),
L('integers','Name a whole number','integer declares a whole-number value. The I0 format prints it without leading padding.',fort('integer :: pencils = 3','write(*,\'(I0)\') pencils + 2'),'5','Start with 6 pencils.','Declare variables before executable steps.'),
L('real-numbers','Use a decimal value','real holds a decimal value. The F3.1 format prints one digit after the decimal point.',fort('real :: length = 2.5','write(*,\'(F3.1)\') length'),'2.5','Try 3.5.','Choose a wider output format for a wider number.'),
L('arrays','Group numbers in an array','An array stores several values. This array has three integer positions.',fort('integer :: scores(3) = [4, 5, 8]','write(*,\'(3(I0,1X))\') scores'),'4 5 8','Change one score.','Array sizes and initial value counts must agree.'),
L('indexing','Read an array position','Fortran arrays normally start at position 1. Parentheses select an item.',fort('integer :: scores(3) = [4, 5, 8]','write(*,\'(I0)\') scores(2)'),'5','Read scores(3).','Do not assume array indexing starts at zero.'),
L('choices','Choose a message','An if block runs one branch based on a logical test.',fort('integer :: score = 8','if (score >= 5) then\n write(*,\'(A)\') "Pass"\nelse\n write(*,\'(A)\') "Try again"\nend if'),'Pass','Try score 3.','Close the block with end if.'),
L('loops','Count with do','A counted do loop includes both its start and end values.',fort('integer :: n','do n = 1, 3\n write(*,\'(I0)\') n\nend do'),'1\n2\n3','Count to 4.','Do not change the loop counter inside the counted loop.'),
L('sum','Add an array','sum adds the values in an array. It is a built-in array operation.',fort('integer :: values(3) = [2, 3, 4]','write(*,\'(I0)\') sum(values)'),'9','Replace 4 with 5.','sum returns a result; it does not change the array.'),
L('where','Change selected array items','where applies a change only where an array condition is true.',fort('integer :: scores(3) = [4, 8, 9]','where (scores >= 7) scores = scores + 1\nwrite(*,\'(3(I0,1X))\') scores'),'4 9 10','Use a limit of 9.','The mask and array must have compatible shapes.'),
L('functions','Return a calculated value','A function has a result. contains separates the main steps from local function definitions.','program lesson\n implicit none\n write(*,\'(I0)\') twice(4)\ncontains\n integer function twice(n) result(answer)\n  integer, intent(in) :: n\n  answer = n * 2\n end function twice\nend program lesson','8','Call twice(7).','Give the function input and result explicit types.'),
L('subroutines','Change a value through a subroutine','A subroutine is called with call. intent(inout) means this input may be changed.','program lesson\n implicit none\n integer :: n = 4\n call double_value(n)\n write(*,\'(I0)\') n\ncontains\n subroutine double_value(value)\n  integer, intent(inout) :: value\n  value = value * 2\n end subroutine double_value\nend program lesson','8','Start n at 7.','Use call for a subroutine; a function is used in an expression.'),
L('allocation','Choose an array size at run time','An allocatable array gets its size when allocate runs. deallocate releases its storage.',fort('integer, allocatable :: scores(:)','allocate(scores(3))\nscores = 0\nwrite(*,\'(I0)\') size(scores)\ndeallocate(scores)'),'3','Allocate four positions.','Allocate before using the array and do not use it after deallocation.')])
course('julia','Julia','julia','Examples use Julia 1.9 or later and built-in tools.','Install Julia. Save each example as lesson.jl and run julia lesson.jl, or paste it into the Julia REPL.','Julia is a language for maths, data and general programming. It combines short code with fast number tools.',[
L('first-message','Print a greeting','println prints a value followed by a newline.','println("Hello, Asha!")','Hello, Asha!','Change the name.','Use double quotes for strings.'),
L('variables','Keep a named number','A variable gives a name to a value. The plus sign adds numbers.','pencils = 3\nprintln(pencils + 2)','5','Start with 6 pencils.','Quoted numbers are text, not values for ordinary arithmetic.'),
L('text','Build a message','A dollar sign inserts a variable into a string.','name = "Ravi"\nprintln("Hi, $name!")','Hi, Ravi!','Insert a score too.','Use $(...) when inserting a calculation.'),
L('arrays','Read an array item','Julia arrays normally start at position 1.','pets = ["cat", "dog"]\nprintln(pets[2])','dog','Read position 1.','A position outside the array raises an error.'),
L('broadcasting','Apply an action to every item','A dot applies an operation element by element. Here each number is doubled.','scores = [2, 3]\nprintln(scores .* 2)','[4, 6]','Multiply each value by 3.','The dot is important when you want item-by-item operations.'),
L('choices','Choose an action','if selects steps using a true-or-false rule. end closes the block.','score = 8\nif score >= 5\n println("Pass")\nelse\n println("Try again")\nend','Pass','Try score 3.','Julia requires a Boolean condition, not a bare number.'),
L('loops','Visit a range','1:3 is a range including both ends. A for loop visits each value.','for n in 1:3\n println(n)\nend','1\n2\n3','Count up to 4.','Close the loop with end.'),
L('functions','Name a short calculation','A short function definition can use an equals sign. The expression is returned.','twice(n) = n * 2\nprintln(twice(4))','8','Call twice(7).','Calling a function needs parentheses around its inputs.'),
L('dictionaries','Use a named key','Dict connects keys with values. The => pair operator joins a key and value.','book = Dict("title" => "Moon Trip", "pages" => "24")\nprintln(book["title"])','Moon Trip','Read pages.','Missing bracket keys throw an error; get can supply a fallback.'),
L('tuples','Group fixed values','A tuple is a fixed group of values. You can unpack its positions into names.','name, score = ("Asha", 8)\nprintln(score)','8','Use score 6.','A tuple itself cannot be changed item by item.'),
L('comprehensions','Build a list with a rule','A comprehension makes values from inputs and an optional filter.','println([n * 2 for n in 1:4 if n > 2])','[6, 8]','Use n > 1 instead.','Read the filter before working out which values are included.'),
L('structs','Group named fields','A struct defines a type with named fields. Ordinary structs are immutable.','struct Book\n title::String\n pages::Int\nend\nbook = Book("Moon Trip", 24)\nprintln(book.pages)','24','Make another Book value.','Use mutable struct only when fields really need changing.')])
course('fsharp','F#','fsharp','Examples use F# with .NET 8 or later.','Install the .NET SDK. Save each example as lesson.fsx and run dotnet fsi lesson.fsx.','F# is a language built around functions and clear data shapes. It works with the .NET tools.',[
L('first-message','Print a greeting','printfn prints formatted output and a new line. %s stands for text.','printfn "%s" "Hello, Asha!"','Hello, Asha!','Change the greeting.','Match the format marker to the value type.'),
L('values','Keep a named value','let gives a name to a value. It cannot be changed unless declared mutable.','let pencils = 3\nprintfn "%d" (pencils + 2)','5','Start with 6 pencils.','Use parentheses to group a calculation passed to printfn.'),
L('functions','Name a calculation','A function is defined with let and an input name. Its expression is the result.','let twice n = n * 2\nprintfn "%d" (twice 4)','8','Call twice 7.','F# function inputs follow the function name with spaces.'),
L('choices','Choose a value','if is an expression with then and else results.','let score = 8\nlet message = if score >= 5 then "Pass" else "Try again"\nprintfn "%s" message','Pass','Try score 3.','The two result branches must agree in type.'),
L('lists','Keep a list','List items are separated by semicolons. List.head reads the first item.','let pets = ["cat"; "dog"]\nprintfn "%s" (List.head pets)','cat','Read a different nonempty list.','List.head fails on an empty list; tryHead returns an option.'),
L('map','Transform each value','List.map applies a function to every item and returns a new list.','let values = [2; 3] |> List.map (fun n -> n * 2)\nprintfn "%A" values','[4; 6]','Multiply by 3.','The pipe sends the list into the next function call.'),
L('filter','Keep matching values','List.filter keeps values that pass a Boolean test.','let values = [4; 8; 9] |> List.filter (fun n -> n >= 7)\nprintfn "%A" values','[8; 9]','Raise the limit to 9.','The test must return true or false.'),
L('tuples','Unpack a pair','A tuple groups values. Pattern matching can give names to its parts.','let name, score = ("Asha", 8)\nprintfn "%d" score','8','Use score 6.','Match the same number of tuple positions.'),
L('records','Group named fields','A record has named fields. A new record can copy an old one with one field changed.','type Book = { Title: string; Pages: int }\nlet book = { Title = "Moon Trip"; Pages = 24 }\nlet longer = { book with Pages = 30 }\nprintfn "%d" longer.Pages','30','Print book.Pages too.','The with expression creates a new value.'),
L('options','Handle an absent value','An option is Some(value) or None. Pattern matching handles both.','let score: int option = None\nlet value = match score with | Some n -> n | None -> 0\nprintfn "%d" value','0','Use Some 8.','Handle None instead of assuming a value exists.'),
L('unions','Name a set of cases','A union describes a fixed set of cases. match selects an action for a case.','type Light = Red | Green\nlet light = Green\nlet message = match light with | Red -> "Stop" | Green -> "Go"\nprintfn "%s" message','Go','Change light to Red.','Cover every union case in a match.'),
L('fold','Combine list values','List.fold carries a result through the list. The starting total is zero here.','let total = [2; 3; 4] |> List.fold (fun sum n -> sum + n) 0\nprintfn "%d" total','9','Use 10 as the starting total.','The starting value affects the result.')])
course('groovy','Groovy','groovy','Examples use Groovy 4 or later with a compatible JDK.','Install a JDK and Groovy. Save each example as lesson.groovy and run groovy lesson.groovy.','Groovy is a language for Java-based tools, scripts and build tasks. It has short syntax for common jobs.',[
L('first-message','Print a greeting','println prints a value with a newline.','println "Hello, Asha!"','Hello, Asha!','Change the name.','Keep quotes around text.'),
L('variables','Name a value','def declares a variable without spelling its type.','def pencils = 3\nprintln pencils + 2','5','Start with 6 pencils.','Use numbers rather than quoted text for addition.'),
L('strings','Build a message','Double-quoted strings can place a variable in the text with a dollar sign.','def name = "Ravi"\nprintln "Hi, $name!"','Hi, Ravi!','Insert a score too.','Single-quoted strings do not expand variables.'),
L('choices','Choose an action','if selects a block based on a rule.','def score = 8\nif (score >= 5) { println "Pass" } else { println "Try again" }','Pass','Try score 3.','Use a clear comparison when testing a score.'),
L('lists','Read a list item','A list stores ordered values. Its first position is zero.','def pets = ["cat", "dog"]\nprintln pets[1]','dog','Read pets[0].','Position 1 is the second item.'),
L('maps','Read a named field','A map pairs keys with values. Dot syntax can read a simple text key.','def book = [title: "Moon Trip", pages: 24]\nprintln book.title','Moon Trip','Read book.pages.','A missing map value may be null; plan for that.'),
L('ranges','Count across a range','The range 1..3 includes both endpoints. each visits the values.','(1..3).each { n -> println n }','1\n2\n3','End the range at 4.','The ..< range leaves out its last endpoint.'),
L('closures','Name a small function','A closure is a block of reusable code. The arrow separates inputs from steps.','def twice = { n -> n * 2 }\nprintln twice(4)','8','Call twice(7).','The last expression is the closure result.'),
L('collect','Transform each item','collect builds a list from a closure result for each item.','println([2, 3].collect { it * 2 })','[4, 6]','Multiply by 3.','it names the input when you omit an explicit closure input.'),
L('find-all','Keep matching items','findAll keeps items for which the closure result is true.','println([4, 8, 9].findAll { it >= 7 })','[8, 9]','Use a limit of 9.','find reads one item, while findAll reads all matching items.'),
L('safe-navigation','Handle a missing object','?. skips a property read on null. The Elvis operator ?: supplies a fallback for a false-like value.','String name = null\nprintln(name?.length() ?: 0)','0','Set name to "Asha".','Elvis uses Groovy truth, so it can replace empty strings and zero too.'),
L('classes','Create an object','A class groups data fields and actions. Groovy supports named property values during construction.','class Book { String title; int pages }\ndef book = new Book(title: "Moon Trip", pages: 24)\nprintln book.title','Moon Trip','Create another book.','Spell property names exactly in the named arguments.')])
